import csv
import io

# Check what stdlib does with four quotes
for tc in ['""""', '"a"""b"', '"a""b"']:
    try:
        reader = csv.reader(io.StringIO(tc))
        result = list(reader)
        print(f'{repr(tc)} -> {result}')
    except Exception as e:
        print(f'{repr(tc)} -> ERROR: {e}')

# Also check: a quoted field containing just one quote should be """" (start, escaped quote, end = 4 quotes)
# But wait: """" = start quote, escaped quote ("), end quote = 3 quotes? No.
# Let's trace: field content is one quote -> """ (start, escaped, end) = 3 quotes
# Actually: to represent a single quote in a field: """ -> that's 3 quotes
# But in CSV: "" = escaped quote, so field with one quote is """ (start, escaped, end)
# Let me check
print()
for tc in ['"""', '""""', '"a"""b"']:
    try:
        reader = csv.reader(io.StringIO(tc))
        result = list(reader)
        print(f'{repr(tc)} -> {result}')
    except Exception as e:
        print(f'{repr(tc)} -> ERROR: {e}')

# What about just a quote in unquoted field?
for tc in ['a"b', '"a"b', 'a"']:
    try:
        reader = csv.reader(io.StringIO(tc))
        result = list(reader)
        print(f'{repr(tc)} -> {result}')
    except Exception as e:
        print(f'{repr(tc)} -> ERROR: {e}')

# And the error cases
for tc in ['"ab"c', '"a"b']:
    try:
        reader = csv.reader(io.StringIO(tc))
        result = list(reader)
        print(f'{repr(tc)} -> {result}')
    except Exception as e:
        print(f'{repr(tc)} -> ERROR: {e}')

# What does stdlib do with quote in middle of unquoted field?
for tc in ['a"b,c', 'a,b"c']:
    try:
        reader = csv.reader(io.StringIO(tc))
        result = list(reader)
        print(f'{repr(tc)} -> {result}')
    except Exception as e:
        print(f'{repr(tc)} -> ERROR: {e}')

